def get_4way_region(grid, target, start=None):
    if start is None:
        for r in range(len(grid)):
            for c in range(len(grid[0])):
                if grid[r][c] == target:
                    grid_copy = [row[:] for row in grid]
                    start = (r, c)
                    break
            if start is not None:
                break
        if start is None:
            return []
    else:
        start = start
    rows = len(grid)
    q = [start]
    region = []
    visited = set()
    while q:
        r, c = q.pop(0)
        if (r, c) in visited:
            continue
        if not (0 <= r < rows and 0 <= c < len(grid[0])):
            continue
        if grid[r][c] != target:
            continue
        visited.add((r, c))
        region.append((r, c))
        for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < len(grid[0]):
                if (nr, nc) not in visited and grid[nr][nc] == target:
                    q.append((nr, nc))
    return region

def find_all_regions(grid, target):
    rows = len(grid)
    visited = set()
    regions = []
    for r in range(rows):
        for c in range(len(grid[0])):
            if grid[r][c] == target and (r, c) not in visited:
                region = get_4way_region(grid, target, (r, c))
                visited.update(region)
                regions.append(region)
    return regions

